// Deja el hilo con la forma que espera nuestro código: id, asunto y mensajes.
// "Traer el hilo entero" entrega un ítem por mensaje, con el cuerpo codificado
// dentro de payload. Del correo solo se toma quién escribe y qué escribió.
const decodificar = (data, charset) => {
  const bytes = Buffer.from(String(data).replace(/-/g, "+").replace(/_/g, "/"), "base64");
  return /8859-1|latin1|windows-1252/i.test(charset || "") ? bytes.toString("latin1") : bytes.toString("utf8");
};
const charsetDe = (tipo) => (String(tipo || "").match(/charset="?([^";\s]+)/i) || [])[1];
const cabecera = (parte, nombre) =>
  (parte.headers || []).find(h => h.name.toLowerCase() === nombre.toLowerCase())?.value;
// Busca la primera parte del tipo pedido, recorriendo las partes anidadas.
const buscar = (parte, tipo, tipoRaiz) => {
  if (!parte) return "";
  if (parte.mimeType === tipo && parte.body?.data) {
    return decodificar(parte.body.data, charsetDe(cabecera(parte, "Content-Type") || tipoRaiz));
  }
  for (const p of parte.parts || []) {
    const t = buscar(p, tipo, tipoRaiz);
    if (t) return t;
  }
  return "";
};
const sinHtml = (html) => html
  .replace(/<(style|script)[\s\S]*?<\/\1>/gi, "")
  .replace(/<br\s*\/?>|<\/p>|<\/div>/gi, "\n")
  .replace(/<[^>]+>/g, "")
  .replace(/&nbsp;/g, " ").replace(/&amp;/g, "&").replace(/&lt;/g, "<").replace(/&gt;/g, ">")
  .replace(/\n{3,}/g, "\n\n").trim();

const items = $input.all().map(i => i.json);
const mensajes = items.map(m => {
  const de = m.From || "";
  const correo = (de.match(/<([^>]+)>/) || [])[1] || de.trim();
  const tipoRaiz = m["Content-Type"];
  const texto = buscar(m.payload, "text/plain", tipoRaiz)
    || sinHtml(buscar(m.payload, "text/html", tipoRaiz))
    || m.snippet || "";
  return {
    de: correo,
    nombre: de.replace(/<.*>/, "").replace(/"/g, "").trim(),
    texto: texto.trim(),
  };
});
const hoy = new Date().toISOString().slice(0, 10);
return [{ json: {
  hilo: { id: items[0]?.threadId || items[0]?.id, asunto: items[0]?.Subject || "", mensajes },
  fecha_hoy: hoy,
  duraciones: "40, 60, 90",
  texto_hilo: mensajes.map(m => `De: ${m.de}\n${m.texto}`).join("\n\n---\n\n"),
}}];

// Junta el hilo con lo que entendió el modelo y arma lo que come nuestro código.
const crudo = $json.text ?? $json.response?.text ?? JSON.stringify($json);
const limpio = String(crudo).replace(/^```(json)?/i, "").replace(/```$/, "").trim();
let lectura;
try { lectura = JSON.parse(limpio); }
catch (e) { throw new Error("El modelo no devolvió un JSON válido: " + limpio.slice(0, 300)); }
const hilo = $('Armar el hilo').first().json.hilo;
return [{ json: { entrada: { pedido: { origen: "buzon", hilo, lectura } } } }];

// REGLA DURA DEL PROYECTO: del calendario real solo se leen horas.
// Los títulos y las descripciones llevan nombres, correos y teléfonos de
// clientes. Acá se tiran en el momento y no salen de este nodo.
const hhmm = (e) => String(e.start?.dateTime || e.start?.date || "").slice(11, 16);
const fin  = (e) => String(e.end?.dateTime || e.end?.date || "").slice(11, 16);
const agenda = [];
for (const sala of ["sala_1", "sala_2"]) {
  let eventos = [];
  try { eventos = $(`Agenda ${sala}`).all().map(i => i.json); } catch (e) { eventos = []; }
  for (const e of eventos) {
    const desde = hhmm(e), hasta = fin(e);
    if (desde && hasta) agenda.push({ sala, desde, hasta });
  }
}
const entrada = $('Armar el pedido').first().json.entrada;
return [{ json: { entrada: { ...entrada, agenda } } }];
